const storageQuantContextFiles={"wal_backup.py": "\"\"\"Observe real SQLite WAL/snapshots/backup; NOT a CSI or power-loss test.\"\"\"\nfrom contextlib import ExitStack, closing\nimport json\nfrom pathlib import Path\nimport shutil\nimport sqlite3\nimport tempfile\n\n\ndef connect(path):\n    return sqlite3.connect(str(path), isolation_level=None, timeout=5)\n\n\ndef view(db):\n    balance, version = db.execute(\"SELECT balance, version FROM account WHERE id=1\").fetchone()\n    total, last = db.execute(\"SELECT SUM(delta), MAX(version) FROM ledger\").fetchone()\n    return {\"balance\": balance, \"version\": version, \"ledger_sum\": total,\n            \"last_ledger_version\": last,\n            \"integrity\": db.execute(\"PRAGMA integrity_check\").fetchone()[0]}\n\n\ndef commit_value(db, balance, version):\n    old = db.execute(\"SELECT balance, version FROM account WHERE id=1\").fetchone()\n    assert version == old[1] + 1\n    db.execute(\"BEGIN IMMEDIATE\")\n    db.execute(\"UPDATE account SET balance=?, version=? WHERE id=1\", (balance, version))\n    db.execute(\"INSERT INTO ledger VALUES(?, ?)\", (version, balance - old[0]))\n    db.commit()\n\n\ndef can_serve(record, minimum_version):\n    return (record[\"integrity\"] == \"ok\" and record[\"version\"] >= minimum_version\n            and record[\"balance\"] == record[\"ledger_sum\"]\n            and record[\"version\"] == record[\"last_ledger_version\"])\n\n\ndef run():\n    with tempfile.TemporaryDirectory(prefix=\"wal-backup-\") as folder, ExitStack() as stack:\n        root = Path(folder)\n        source = root / \"source.sqlite\"\n        writer = stack.enter_context(closing(connect(source)))\n        assert writer.execute(\"PRAGMA journal_mode=WAL\").fetchone()[0] == \"wal\"\n        writer.execute(\"PRAGMA wal_autocheckpoint=0\")\n        writer.executescript(\"\"\"\n        CREATE TABLE account(id INTEGER PRIMARY KEY, balance INTEGER, version INTEGER);\n        CREATE TABLE ledger(version INTEGER PRIMARY KEY, delta INTEGER);\n        BEGIN;\n        INSERT INTO account VALUES(1,100,1);\n        INSERT INTO ledger VALUES(1,100);\n        COMMIT;\n        \"\"\")\n        # Make version 1 present in the main file before the controlled WAL writes.\n        writer.execute(\"PRAGMA wal_checkpoint(TRUNCATE)\")\n        commit_value(writer, 120, 2)\n        assert (root / \"source.sqlite-wal\").stat().st_size > 0\n\n        # No concurrent write occurs during this copy. It is deliberately incomplete:\n        # committed version 2 remains in WAL, which this main-file-only copy omits.\n        raw_path = root / \"main-only.sqlite\"\n        shutil.copyfile(source, raw_path)\n        raw = stack.enter_context(closing(connect(raw_path)))\n        raw_record = view(raw)\n        assert raw_record[\"version\"] == 1\n\n        reader = stack.enter_context(closing(connect(source)))\n        reader.execute(\"BEGIN\")\n        before = view(reader)  # First SELECT establishes this read snapshot.\n        commit_value(writer, 130, 3)\n        after = view(reader)\n        assert before == after and after[\"version\"] == 2\n        assert view(writer)[\"version\"] == 3\n\n        frozen = stack.enter_context(closing(connect(root / \"snapshot-2.sqlite\")))\n        reader.backup(frozen)\n        snapshot_2 = view(frozen)\n        assert snapshot_2 == after\n        reader.rollback()\n\n        fresh = stack.enter_context(closing(connect(source)))\n        backup = stack.enter_context(closing(connect(root / \"backup-3.sqlite\")))\n        fresh.backup(backup)\n        backup_3 = view(backup)\n        assert backup_3[\"version\"] == 3\n        assert not can_serve(snapshot_2, 3) and can_serve(backup_3, 3)\n\n        # Retaining the live volume also retains a later, logically mistaken write.\n        commit_value(writer, 999, 4)\n        retained = view(writer)\n        assert retained[\"balance\"] == 999\n\n        # Restore through the database API into a separate location, then resume work.\n        restored = stack.enter_context(closing(connect(root / \"isolated-restore.sqlite\")))\n        backup.backup(restored)\n        restore_before = view(restored)\n        assert restore_before == backup_3 and can_serve(restore_before, 3)\n        commit_value(restored, 131, 4)\n        resumed = view(restored)\n        assert resumed[\"balance\"] == resumed[\"ledger_sum\"] == 131\n        return {\"sqlite\": sqlite3.sqlite_version,\n                \"main_file_only\": raw_record,\n                \"reader_snapshot_before_writer\": before,\n                \"same_reader_after_writer\": after,\n                \"backup_from_snapshot\": snapshot_2,\n                \"backup_from_fresh_connection\": backup_3,\n                \"retained_after_bad_write\": retained,\n                \"isolated_restore\": restore_before, \"consumer_continued\": resumed,\n                \"checks\": {\"wal_contains_committed_change\": True,\n                           \"old_but_consistent_backup_rejected_for_minimum_3\": True,\n                           \"fresh_backup_passes_minimum_3\": True}}\n\n\nif __name__ == \"__main__\":\n    print(json.dumps(run(), ensure_ascii=False, indent=2))\n", "volume_writer.py": "\"\"\"One mounted-path writer used unchanged in local checks and Kubernetes Jobs.\n\nRun without flags for a temporary local test, or --db PATH --op STABLE_ID.\nThis verifies only this SQLite effect protocol; cluster storage needs its own run.\n\"\"\"\nimport argparse\nfrom contextlib import closing\nimport json\nfrom pathlib import Path\nimport sqlite3\nimport tempfile\n\n\ndef write_once(path, op):\n    with closing(sqlite3.connect(str(path), isolation_level=None, timeout=10)) as db:\n        db.execute(\"BEGIN IMMEDIATE\")\n        db.execute(\"CREATE TABLE IF NOT EXISTS counter(id INTEGER PRIMARY KEY, value INTEGER)\")\n        db.execute(\"CREATE TABLE IF NOT EXISTS receipt(op TEXT PRIMARY KEY, before INTEGER, after INTEGER)\")\n        db.execute(\"INSERT OR IGNORE INTO counter VALUES(1,0)\")\n        receipt = db.execute(\"SELECT before,after FROM receipt WHERE op=?\", (op,)).fetchone()\n        duplicate = receipt is not None\n        if receipt is None:\n            before = db.execute(\"SELECT value FROM counter WHERE id=1\").fetchone()[0]\n            receipt = (before, before + 1)\n            db.execute(\"UPDATE counter SET value=? WHERE id=1\", (receipt[1],))\n            db.execute(\"INSERT INTO receipt VALUES(?,?,?)\", (op, *receipt))\n        current = db.execute(\"SELECT value FROM counter WHERE id=1\").fetchone()[0]\n        db.commit()\n        return {\"op\":op,\"before\":receipt[0],\"after\":receipt[1],\n                \"duplicate\":duplicate,\"current_counter\":current}\n\n\ndef local_test():\n    with tempfile.TemporaryDirectory(prefix=\"volume-writer-\") as folder:\n        path=Path(folder,'counter.sqlite')\n        results=[write_once(path,op) for op in ('write-1','write-2','write-1')]\n        assert [r['after'] for r in results] == [1,2,1]\n        assert [r['duplicate'] for r in results] == [False,False,True]\n        assert [r['current_counter'] for r in results] == [1,2,2]\n        return {'sequence':results,'final_counter':2,'cluster_executed':False}\n\n\nif __name__=='__main__':\n    parser=argparse.ArgumentParser()\n    parser.add_argument('--db',type=Path)\n    parser.add_argument('--op')\n    args=parser.parse_args()\n    if bool(args.db) != bool(args.op):\n        parser.error('--db and --op must be supplied together')\n    result=write_once(args.db,args.op) if args.db else local_test()\n    print(json.dumps(result,ensure_ascii=False,indent=2))\n", "int4_groups.py": "\"\"\"Original INT4 packing and numerical oracle, standard library only.\n\nThis is a CPU reference implementation, not a GPU kernel or engine benchmark.\nWeights use symmetric [-7,7], zero-point 0, float32 scales, round-to-even.\n\"\"\"\nimport json\nimport math\nfrom pathlib import Path\nimport struct\nimport tempfile\n\n\nW = [[12, .12, -.18, .09, .24, -.30, .06, -.12],\n     [.08, -.16, .24, -.32, .40, -.48, .56, -.64],\n     [.03, .06, -.09, .12, -.15, .18, -.21, .24],\n     [-.20, .10, .30, -.40, .50, -.60, .70, -.80]]\nINPUTS = [[1, -1, .5, .25, -.5, .75, -1, 1],\n          [.1, .2, .3, .4, .5, .6, .7, .8]]\nBIAS = [.1, -.2, .3, -.4]\nHEADER = struct.Struct(\"<4sHHHH\")\n\n\ndef f32(value):\n    return struct.unpack(\"<f\", struct.pack(\"<f\", value))[0]\n\n\ndef pack(values):\n    assert all(type(q) is int and -7 <= q <= 7 for q in values)\n    payload = bytearray((len(values) + 1) // 2)\n    for i, q in enumerate(values):\n        payload[i // 2] |= (q & 15) << (4 * (i % 2))\n    return bytes(payload)\n\n\ndef unpack(payload, count):\n    if len(payload) != (count + 1) // 2:\n        raise ValueError(\"payload_length\")\n    values = []\n    for i in range(count):\n        nibble = (payload[i // 2] >> (4 * (i % 2))) & 15\n        q = nibble - 16 if nibble >= 8 else nibble\n        if q == -8:\n            raise ValueError(\"unused_symmetric_code\")\n        values.append(q)\n    return values\n\n\ndef group_ranges(size, group_size):\n    return [(i, min(i + group_size, size)) for i in range(0, size, group_size)]\n\n\ndef quantize(flat, group_size):\n    q, scales = [], []\n    for begin, end in group_ranges(len(flat), group_size):\n        values = flat[begin:end]\n        maximum = max(abs(x) for x in values)\n        scale = f32(maximum / 7) if maximum else 1.0\n        scales.append(scale)\n        q.extend(max(-7, min(7, round(x / scale))) for x in values)\n    return q, scales\n\n\ndef dequantize(q, scales, group_size):\n    return [value * scales[i // group_size] for i, value in enumerate(q)]\n\n\ndef forward(flat, x):\n    return [sum(flat[j * 8 + i] * x[i] for i in range(8)) + BIAS[j] for j in range(4)]\n\n\ndef integer_group_forward(qw, scales, group_size, qx, sx):\n    # A different weight scale requires a separate partial sum before rescaling.\n    output = []\n    for row in range(4):\n        value = BIAS[row]\n        for begin in range(0, 8, group_size):\n            end = min(begin + group_size, 8)\n            accumulator = sum(qx[i] * qw[row * 8 + i] for i in range(begin, end))\n            value += accumulator * sx * scales[(row * 8 + begin) // group_size]\n        output.append(value)\n    return output\n\n\ndef activation(x, maximum):\n    scale = maximum / 127\n    q = [max(-127, min(127, round(v / scale))) for v in x]\n    return q, scale, sum(abs(v) > maximum for v in x)\n\n\ndef run():\n    flat = [v for row in W for v in row]\n    reference = [forward(flat, x) for x in INPUTS]\n    # Independently expanded decimal dot products (including BIAS).\n    assert all(abs(a-b) < 1e-12 for a,b in zip(reference[0], [11.3875, -1.68, .915, -2.85]))\n    schemes = {}\n    with tempfile.TemporaryDirectory(prefix=\"int4-groups-\") as folder:\n        for label, group_size in ((\"per_tensor\", 32), (\"per_channel\", 8),\n                                  (\"group_4\", 4), (\"group_2\", 2)):\n            q, scales = quantize(flat, group_size)\n            payload = pack(q)\n            header = HEADER.pack(b\"IGQ1\", 4, 8, group_size, len(scales))\n            encoded = header + struct.pack(\"<\" + \"f\" * len(scales), *scales) + payload\n            path = Path(folder, label + \".igq\")\n            path.write_bytes(encoded)\n            data = path.read_bytes()\n            magic, rows, cols, group, count = HEADER.unpack(data[:HEADER.size])\n            assert (magic, rows, cols, group, count) == (b\"IGQ1\", 4, 8, group_size, len(scales))\n            split = HEADER.size + 4 * count\n            loaded_scales = list(struct.unpack(\"<\" + \"f\" * count, data[HEADER.size:split]))\n            loaded_q = unpack(data[split:], rows * cols)\n            assert loaded_scales == scales and loaded_q == q\n            decoded = dequantize(loaded_q, loaded_scales, group)\n            outputs = [forward(decoded, x) for x in INPUTS]\n            error = max(abs(y - target) for a,b in zip(outputs, reference) for y,target in zip(a,b))\n            schemes[label] = {\"group_size\": group_size, \"scales\": scales, \"integers\": q,\n                              \"payload_hex\": payload.hex(), \"integer_bytes\": len(payload),\n                              \"scale_bytes\": 4 * count, \"header_bytes\": HEADER.size,\n                              \"file_bytes\": len(data), \"tensor_bytes\": len(payload) + 4 * count,\n                              \"weight_mae\": sum(abs(a-b) for a,b in zip(flat, decoded))/len(flat),\n                              \"max_output_error\": error, \"outputs\": outputs}\n    assert schemes[\"group_4\"][\"max_output_error\"] < schemes[\"per_tensor\"][\"max_output_error\"]\n    assert schemes[\"group_2\"][\"tensor_bytes\"] > len(flat) * 2\n    assert unpack(pack([-7, -1, 0, 7, 3]), 5) == [-7, -1, 0, 7, 3]\n    zero_q, zero_scales = quantize([0.0] * 3, 2)\n    assert dequantize(zero_q, zero_scales, 2) == [0.0] * 3\n\n    qw, sw = quantize(flat, 4)\n    held_out = [.1, -.2, .3, -.4, .5, -.1, .2, 3.0]\n    static_q, static_s, clipped = activation(held_out, .5)\n    dynamic_q, dynamic_s, _ = activation(held_out, max(abs(x) for x in held_out))\n    deq_w = dequantize(qw, sw, 4)\n    target = forward(deq_w, held_out)  # Isolate activation error from weight error.\n    static_out = integer_group_forward(qw, sw, 4, static_q, static_s)\n    dynamic_out = integer_group_forward(qw, sw, 4, dynamic_q, dynamic_s)\n    dq_x = [q * dynamic_s for q in dynamic_q]\n    assert max(abs(a-b) for a,b in zip(dynamic_out, forward(deq_w, dq_x))) < 1e-12\n    wrong = [sum(dynamic_q[i] * qw[row * 8+i] for i in range(8)) * dynamic_s * sw[0] + BIAS[row]\n             for row in range(4)]\n    static_error = max(abs(a-b) for a,b in zip(static_out, target))\n    dynamic_error = max(abs(a-b) for a,b in zip(dynamic_out, target))\n    assert clipped == 1 and static_error > dynamic_error\n    assert max(abs(a-b) for a,b in zip(wrong, dynamic_out)) > 1\n    return {\"shape\": [4,8], \"fp16_weight_bytes\": 64, \"reference_outputs\": reference,\n            \"schemes\": schemes,\n            \"activation_probe\": {\"calibration_max\": .5, \"held_out_max\": 3.0,\n                                 \"clipped_values\": clipped, \"static_max_error\": static_error,\n                                 \"dynamic_max_error\": dynamic_error,\n                                 \"group_rescale_matches_dequantized_dot\": True,\n                                 \"single_scale_wrong_output\": wrong},\n            \"edge_checks\": {\"signed_odd_roundtrip\": True, \"all_zero_group\": True},\n            \"execution\": \"stdlib_cpu_reference_no_quantized_kernel\"}\n\n\nif __name__ == \"__main__\":\n    print(json.dumps(run(), ensure_ascii=False, indent=2))\n", "context_state.py": "\"\"\"SQLite authority versus stale text; deterministic fixtures, no model calls.\"\"\"\nfrom contextlib import closing\nimport json\nfrom pathlib import Path\nimport sqlite3\nimport tempfile\n\n\ndef connect(path):\n    return sqlite3.connect(str(path), isolation_level=None)\n\n\ndef setup(path):\n    with closing(connect(path)) as db:\n        db.executescript(\"\"\"\n        CREATE TABLE task(id TEXT PRIMARY KEY, tenant TEXT, version INTEGER,\n                          state TEXT, original_op TEXT);\n        CREATE TABLE effect(op TEXT PRIMARY KEY, value INTEGER);\n        CREATE TABLE source(id TEXT PRIMARY KEY, version INTEGER, value INTEGER);\n        CREATE TABLE memory(id TEXT PRIMARY KEY, subject TEXT, source_id TEXT,\n                            source_version INTEGER, expires INTEGER, retracted INTEGER);\n        INSERT INTO task VALUES('R17','A',1,'RUNNING','R17:publish');\n        INSERT INTO source VALUES('pool-limit',2,10);\n        INSERT INTO memory VALUES('old','user-A','pool-limit',1,1000,0);\n        INSERT INTO memory VALUES('current','user-A','pool-limit',2,1000,0);\n        INSERT INTO memory VALUES('other-user','user-B','pool-limit',2,1000,0);\n        INSERT INTO memory VALUES('expired','user-A','pool-limit',2,10,0);\n        \"\"\")\n\n\ndef receiver(db, op):\n    db.execute(\"INSERT OR IGNORE INTO effect VALUES(?,13)\", (op,))\n\n\ndef complete_task(db):\n    db.execute(\"BEGIN IMMEDIATE\")\n    task = db.execute(\"SELECT state,original_op FROM task WHERE id='R17'\").fetchone()\n    assert task[0] == \"RUNNING\"\n    receiver(db, task[1])\n    db.execute(\"UPDATE task SET state='SUCCEEDED',version=version+1 WHERE id='R17'\")\n    db.commit()\n\n\ndef lookup_memory(db, identity, now, references=None):\n    rows = db.execute(\"\"\"\n        SELECT m.id,m.source_version,s.version,s.value\n        FROM memory m JOIN source s ON s.id=m.source_id\n        WHERE m.subject=? AND m.expires>? AND m.retracted=0\n        ORDER BY m.id\n    \"\"\", (identity, now)).fetchall()\n    accepted, stale = [], []\n    for memory_id, recorded, current, value in rows:\n        if references is not None and memory_id not in references:\n            continue\n        if recorded != current:\n            stale.append(memory_id)\n        else:\n            accepted.append({\"memory_id\": memory_id, \"source_version\": current, \"value\": value})\n    return {\"accepted\": accepted, \"stale_for_current_fact\": stale}\n\n\ndef run():\n    with tempfile.TemporaryDirectory(prefix=\"context-state-\") as folder:\n        path = Path(folder, \"good.sqlite\")\n        setup(path)\n        stale_summary = {\"task\": \"R17\", \"task_version\": 1, \"state\": \"RUNNING\",\n                         \"original_op\": \"R17:publish\", \"text\": \"报告尚未保存\"}\n        with closing(connect(path)) as db:\n            complete_task(db)\n            # Recover without conversation text: authority still has the actual result.\n            state, version, op = db.execute(\"SELECT state,version,original_op FROM task WHERE id='R17'\").fetchone()\n            assert state == \"SUCCEEDED\"\n            receipt = db.execute(\"SELECT value FROM effect WHERE op=?\", (op,)).fetchone()[0]\n            effects_after_recovery = db.execute(\"SELECT COUNT(*) FROM effect\").fetchone()[0]\n            assert receipt == 13 and effects_after_recovery == 1\n\n            # An old model view cannot overwrite newer task state using a guarded update.\n            changed = db.execute(\"UPDATE task SET state='RUNNING',version=version+1 WHERE id='R17' AND version=?\",\n                                 (stale_summary[\"task_version\"],)).rowcount\n            assert changed == 0\n            assert db.execute(\"SELECT state,version FROM task\").fetchone() == (\"SUCCEEDED\",2)\n\n            selected = lookup_memory(db, \"user-A\", 100)\n            assert selected == {\"accepted\": [{\"memory_id\":\"current\",\"source_version\":2,\"value\":10}],\n                                \"stale_for_current_fact\": [\"old\"]}\n            # A cached reference exists, but assembly rechecks its current status.\n            cached_reference = [\"current\"]\n            db.execute(\"UPDATE memory SET retracted=1 WHERE id='current'\")\n            after_retract = lookup_memory(db, \"user-A\", 100, cached_reference)\n            assert after_retract[\"accepted\"] == []\n\n        bad_path = Path(folder, \"bad-policy.sqlite\")\n        setup(bad_path)\n        with closing(connect(bad_path)) as db:\n            complete_task(db)\n            # Deliberately wrong recovery policy: trust old text and invent a new op.\n            if stale_summary[\"state\"] == \"RUNNING\":\n                receiver(db, \"R17:new-op-from-stale-summary\")\n            bad_effects = db.execute(\"SELECT COUNT(*) FROM effect\").fetchone()[0]\n            assert bad_effects == 2\n\n        original = {\"claim\": \"driver_timeout\", \"status\": \"hypothesis\",\n                    \"applies_to\": \"driver-v1\", \"window\": \"10:00-10:05\",\n                    \"latency\": 120, \"unit\": \"ms\", \"evidence_ref\": \"trace-8:v1\"}\n        compressed = {key: original[key] for key in original}\n        bad_compressed = dict(compressed, status=\"confirmed\", applies_to=\"all_versions\")\n        # Fixed semantic slots are checked; no claim of general natural-language equivalence.\n        def preserves_slots(summary):\n            return all(summary.get(key) == value for key,value in original.items())\n        assert preserves_slots(compressed) and not preserves_slots(bad_compressed)\n        return {\"correct_recovery\": {\"authority_state\":state,\"authority_version\":version,\n                                     \"original_op\":op,\"receipt\":receipt,\"effects\":effects_after_recovery,\n                                     \"stale_update_rows\":changed,\"needs_chat_history\":False},\n                \"negative_summary_recovery\": {\"effects\":bad_effects,\"created_new_op\":True},\n                \"memory_selection\":selected,\"after_retraction\":after_retract,\n                \"summary_slot_checks\": {\"qualified_summary\":True,\"changed_certainty_rejected\":True},\n                \"execution\":\"local_sqlite_fixed_facts_no_llm_or_kairo\"}\n\n\nif __name__ == \"__main__\":\n    print(json.dumps(run(), ensure_ascii=False, indent=2))\n", "int8_runtime.py": "\"\"\"Actual PyTorch 2.5.1 CPU dynamic INT8 Linear, separate from the INT4 format.\n\nCreates/loads only its own TorchScript file. No downloaded model or GPU is used.\n\"\"\"\nimport json\nfrom pathlib import Path\nimport tempfile\n\nimport torch\nfrom int4_groups import W, INPUTS, BIAS\n\n\ndef run():\n    torch.set_num_threads(1)\n    supported = torch.backends.quantized.supported_engines\n    if torch.backends.quantized.engine == 'none':\n        engine = next((name for name in ('qnnpack','x86','fbgemm') if name in supported), None)\n        if engine is None:\n            raise RuntimeError('This PyTorch build has no usable quantized CPU backend')\n        torch.backends.quantized.engine = engine\n    model = torch.nn.Sequential(torch.nn.Linear(8, 4)).eval()\n    with torch.no_grad():\n        model[0].weight.copy_(torch.tensor(W, dtype=torch.float32))\n        model[0].bias.copy_(torch.tensor(BIAS, dtype=torch.float32))\n    inputs = torch.tensor(INPUTS, dtype=torch.float32)\n    quantized = torch.ao.quantization.quantize_dynamic(model, {torch.nn.Linear}, dtype=torch.qint8)\n    with torch.inference_mode():\n        reference = model(inputs)\n        output = quantized(inputs)\n    weight = quantized[0].weight()\n    assert weight.dtype == torch.qint8\n    assert not isinstance(quantized[0], torch.nn.Linear)\n    max_error = float((output - reference).abs().max())\n    # A declared numerical tolerance for THESE fixed linear inputs, not model quality.\n    assert torch.isfinite(output).all() and max_error < 0.2\n    with tempfile.TemporaryDirectory(prefix=\"int8-runtime-\") as folder:\n        path = Path(folder, \"own-linear.pt\")\n        traced = torch.jit.trace(quantized, inputs)\n        torch.jit.save(traced, str(path))\n        restored = torch.jit.load(str(path)).eval()\n        with torch.inference_mode():\n            loaded_output = restored(inputs)\n        roundtrip_error = float((loaded_output - output).abs().max())\n        assert roundtrip_error == 0\n        artifact_bytes = path.stat().st_size\n    return {\"torch\":torch.__version__, \"device\":\"cpu\",\n            \"quantized_engine\":torch.backends.quantized.engine,\n            \"module_type\":type(quantized[0]).__module__+'.'+type(quantized[0]).__name__,\n            \"weight_dtype\":str(weight.dtype), \"scheme\":str(weight.qscheme()),\n            \"weight_integer_payload_bytes\":weight.int_repr().numel(),\n            \"fp32_weight_payload_bytes\":model[0].weight.numel() * model[0].weight.element_size(),\n            \"reference_outputs\":reference.tolist(), \"quantized_outputs\":output.tolist(),\n            \"fixed_input_max_abs_error\":max_error,\n            \"declared_fixed_input_error_limit\":0.2,\n            \"torchscript_roundtrip_max_abs_error\":roundtrip_error,\n            \"whole_torchscript_artifact_bytes\":artifact_bytes,\n            \"execution\":\"actual_cpu_dynamic_int8_not_int4_no_latency_benchmark\"}\n\n\nif __name__ == \"__main__\":\n    print(json.dumps(run(), ensure_ascii=False, indent=2))\n"};
